"""Bass Pro Shops navigation taxonomy (generated from the live mega-nav).

Source of truth: ``__NEXT_DATA__.props.megaNavHtmlV2`` served by
``https://www.basspro.com/c/<department>`` (captured 2026-10-03).

Inventory captured from that blob:

* 11 level-1 departments (``/c/<slug>``)
* 116 level-2 categories (``/l/<slug>``, ``/c/<slug>`` or ``/b/<slug>``)
* 782 level-3 subcategories (``/l/<slug>``, ``/b/<slug>``)
* 909 crawlable entries in total (39 marketing tiles such as
  "Sale" / "New Arrivals" carry no browse URL and are skipped)

Every entry keeps its full navigation path in ``category`` so the ~120 URLs that
are linked from more than one department (for example ``/l/life-jackets``) stay
addressable per department; the spider also accepts the bare ``slug``.
"""

from __future__ import annotations

BASSPRO_BASE_URL = 'https://www.basspro.com'

# Coveo Headless search organization used by the Bass Pro storefront.
BASSPRO_COVEO_ORGANIZATION_ID = "bassproshopsproductionl92epymr"
BASSPRO_COVEO_SEARCH_URL = (
    "https://platform.cloud.coveo.com/rest/search/v2"
    "?organizationId=" + BASSPRO_COVEO_ORGANIZATION_ID
)
# searchHub selects the storefront query pipeline (ProductionPipeline).
BASSPRO_COVEO_SEARCH_HUB = "basspro-searchhub"
# First-party short-lived search token endpoint (valid for ~4 hours).
BASSPRO_TOKEN_PATH = "/api/v1/coveo/generate-token"
BASSPRO_TOKEN_URL = BASSPRO_BASE_URL + BASSPRO_TOKEN_PATH + "?refresh=true"

# Advanced query the storefront always applies (firearms / ammo / restricted SKUs).
BASSPRO_DEFAULT_AQ = (
    'NOT (@isgun==1 OR @isammo=="1" OR @isgooglerestricted=="1")'
)

